<script setup lang="ts">
import {ref,computed} from 'vue';import {useRouter} from 'vue-router';import {useWorkbench} from '../stores/workbench';import {api,post,fmt,percent} from '../api/client';import EChart from '../components/EChart.vue';import StatusBadge from '../components/StatusBadge.vue';import UiIcon from '../components/UiIcon.vue';const s=useWorkbench(),router=useRouter(),setId=ref('demo'),name=ref('内置 D1–D10 演示测试集'),engine=ref('demo'),report=ref<any>(null),busy=ref(false),replay=ref<any>(null),replayOpen=ref(false);
async function run(){busy.value=true;try{report.value=await post('/testsets/'+encodeURIComponent(setId.value)+'/run',{engine:engine.value})}catch(e:any){s.error=e.message}finally{busy.value=false}}
async function upload(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;try{const form=new FormData();form.append('file',f);const x=await api('/testsets',{method:'POST',body:form});setId.value=x.id;name.value=f.name;report.value=null;}catch(e:any){s.error=e.message}}
function reopen(row:any){s.instruction=row.instruction;s.engine=engine.value;router.push('/workbench').then(()=>s.start().catch(()=>{}));}
const token=(name:string)=>getComputedStyle(document.documentElement).getPropertyValue(name).trim();const chart=computed(()=>({tooltip:{trigger:'axis'},grid:{left:48,right:20,top:20,bottom:35},xAxis:{type:'category',data:(report.value?.by_level||[]).map((x:any)=>x.level),axisLine:{lineStyle:{color:token('--line')}}},yAxis:{type:'value',max:100,axisLabel:{formatter:'{value}%'},splitLine:{lineStyle:{color:token('--line')}}},series:[{type:'bar',barWidth:34,data:(report.value?.by_level||[]).map((x:any)=>Math.round(x.accuracy*100)),itemStyle:{color:token('--primary'),borderRadius:[5,5,0,0]},label:{show:true,position:'top',formatter:'{c}%'}}]}));
</script><template><div class="page-heading"><div><div class="eyebrow">可复现评估 / M8</div><h1>建模测评</h1><p>按 L1–L4 核对指令解析、模型规格与幻觉检查。</p></div><span class="page-icon"><UiIcon name="chart" :size="30"/></span></div><section class="panel panel-pad"><div class="toolbar"><div><h2>{{name}}</h2><p class="muted">参考项：层级 · 参数修改 Δπ · 结构算子 s · 预期错误</p></div><div class="actions"><el-select v-model="engine" class="medium-select"><el-option label="演示规则引擎" value="demo"/><el-option label="本地 Qwen" value="openai"/></el-select><label class="upload-button secondary"><input type="file" accept=".json,.csv" @change="upload"/>导入测试集</label><el-button type="primary" :loading="busy" @click="run" data-testid="run-evaluation">运行测评</el-button></div></div><div class="notice"><UiIcon name="info"/><span>规格级测评 · 目标值比对 <StatusBadge name="目标值比对测评"/></span></div></section><template v-if="report"><div class="evaluation-context"><span>{{report.total}} 条用例 · 规格级比对</span><span>实际引擎：{{[...new Set((report.cases||[]).map((x:any)=>x.parse?.engine||'未记录'))].join(' / ')}}</span></div><div class="stat-grid"><div class="stat-card"><span>本测试集规格级匹配率</span><strong>{{percent(report.accuracy)}}<small>{{report.passed}} / {{report.scored??report.total}}</small></strong></div><div class="stat-card"><span>Δπ 精确率 / 召回率</span><strong class="smaller-stat">{{percent(report.precision)}} / {{percent(report.recall)}}</strong></div><div class="stat-card"><span>疑似幻觉项</span><strong>{{report.hallucinations}}<small>W501 + E101</small></strong></div><div class="stat-card"><span>平均处理耗时</span><strong>{{fmt(report.mean_ms)}}<small>ms</small></strong></div></div><div class="two-columns align-start"><section class="panel panel-pad"><h2>按层级匹配率</h2><EChart :option="chart" height="260px"/></section><section class="panel panel-pad"><h2>报告口径</h2><p>数值相对误差 ≤ 1%，参数按对象、字段、操作或方向、幅度及生效时段匹配。</p><p>must_fail 用例只有报出期望错误才通过；人工改选的层级不参与准确率统计。</p><p class="small-note">未标注 {{report.unlabeled||0}} 条；未标注用例不计入准确率。</p><div class="actions"><a class="download-link" :href="'/api/testsets/'+setId+'/report?format=md'" download><UiIcon name="download"/>Markdown 报告</a><a class="download-link" :href="'/api/testsets/'+setId+'/report?format=csv'" download><UiIcon name="download"/>CSV 明细</a></div></section></div><section class="panel panel-pad"><h2>逐条用例</h2><el-table :data="report.cases" stripe><el-table-column prop="id" label="编号" width="75"/><el-table-column prop="instruction" label="调度指令" min-width="290"/><el-table-column prop="expected_level" label="参考层级" width="100"/><el-table-column prop="actual_level" label="程序判级" width="100"/><el-table-column label="匹配结果" width="100"><template #default="{row}"><span :class="row.passed?'text-success':'text-danger'">{{row.passed===null?'未标注':row.passed?'通过':'不匹配'}}</span></template></el-table-column><el-table-column label="回放" width="150"><template #default="{row}"><el-button text @click="replay=row;replayOpen=true">详情</el-button><el-button text @click="reopen(row)">载入</el-button></template></el-table-column></el-table></section></template><section v-else class="panel empty-evaluation"><UiIcon name="chart" :size="44"/><h2>准备运行第一组测评</h2><p>内置 10 条真实编号场景，覆盖 L1–L4、未知对象与孤岛风险。</p></section><el-dialog v-model="replayOpen" title="用例回放" width="800px"><template v-if="replay"><blockquote>{{replay.instruction}}</blockquote><h3>解析与规格</h3><pre class="json-block">{{JSON.stringify(replay.parse,null,2)}}</pre><h3>校验与差异</h3><pre class="json-block">{{JSON.stringify({errors:replay.errors,check:replay.check},null,2)}}</pre></template></el-dialog></template>